-- Star Wars: Thrawn Trilogy -- logistics: limited proton torpedoes and
-- theatre-appropriate recall lists (owner requests, 2026-10-14).
--
-- Torpedoes: a weapon carrying the [dummy] special sw_special_torpedo_magazine
-- (volleys=N, generated by production/tools/gen_hte_units.py) can be used in N
-- fights per mission, attacking or firing back. Each fight it is used in adds
-- one to the unit variable sw_torpedo_volleys; at N the unit is marked
-- sw_torpedoes_out, which the weapon's [disable] special filters on. Both are
-- cleared at every mission's prestart (the magazine is refilled).
--
-- Recall: a mission with open space or asteroid terrain is a space battle.
-- At the start event (after the scenario's own prestart has placed and
-- transformed its heroes), side-1 units left on the recall list that do not
-- belong in this theatre -- starships in a ground battle, ground units in a
-- space battle -- are set aside in sw_stashed_heroes, which
-- {SW_VICTORY_HOUSEKEEPING} returns to the recall list at victory.

local core = wesnoth.require("~add-ons/Star_Wars_Thrawn_Trilogy/lua/sw_core.lua")
local _ = wesnoth.textdomain("wesnoth-Star_Wars_Thrawn_Trilogy")

local logistics = {}

logistics.MAGAZINE = "sw_special_torpedo_magazine"
logistics.CRAFT = { sw_starfighter = true, sw_capital = true }

-- Volleys a unit's named weapon may fire per mission, or nil if unlimited.
function logistics.magazine(u, weapon_name)
	for _i, a in ipairs(u.attacks) do
		if a.name == weapon_name then
			for _j, sp in ipairs(a.specials) do
				if sp[1] == "dummy" and sp[2].id == logistics.MAGAZINE then return tonumber(sp[2].volleys) end
			end
		end
	end
	return nil
end

function logistics.refill(u)
	u.variables.sw_torpedo_volleys = nil
	u.variables.sw_torpedoes_out = nil
end

function logistics.on_prestart()
	for _i, u in ipairs(wesnoth.units.find_on_map{}) do logistics.refill(u) end
	for _i, u in ipairs(wesnoth.units.find_on_recall{}) do logistics.refill(u) end
end

-- attack end: count a volley for each combatant whose weapon has a magazine.
-- The weapons used are the WML variables $weapon and $second_weapon during
-- attack events (the Lua event context does not carry them).
function logistics.on_attack_end()
	local ctx = wesnoth.current.event_context
	for _i, side in ipairs{ { ctx.x1, ctx.y1, wml.variables["weapon.name"] },
	                         { ctx.x2, ctx.y2, wml.variables["second_weapon.name"] } } do
		local weapon_name = side[3]
		local u = weapon_name and wesnoth.units.get(side[1], side[2])
		local volleys = u and logistics.magazine(u, weapon_name)
		if volleys then
			local used = core.number(u.variables.sw_torpedo_volleys, 0) + 1
			u.variables.sw_torpedo_volleys = used
			local left = math.max(0, volleys - used)
			if left == 0 then u.variables.sw_torpedoes_out = true end
			core.float(u.x, u.y, left == 0 and tostring(_ "torpedoes spent")
				or (tostring(_ "torpedo volleys left:") .. " " .. left), "#ffc04a")
		end
	end
end

function logistics.is_space_battle()
	return #wesnoth.map.find{ terrain = "Qsp,Qsa" } > 0
end

-- start: set aside units that cannot fight in this theatre. Stored with the
-- engine's own [store_unit] and appended the way {SW_STASH_HEROES} does, with
-- the underlying_id dropped: a unit config copied through Lua loses that
-- 64-bit id to floating point, and restored units with colliding ids
-- overwrite each other (found in an engine probe, 2026-10-14).
function logistics.sort_recall_list()
	local space = logistics.is_space_battle()
	local ids = {}
	for _i, u in ipairs(wesnoth.units.find_on_recall{ side = 1 }) do
		local unit_type = wesnoth.unit_types[u.type]
		local craft = unit_type ~= nil and logistics.CRAFT[unit_type.__cfg.movement_type] == true
		if craft ~= space then table.insert(ids, u.id) end
	end
	if #ids == 0 then return end
	wesnoth.wml_actions.store_unit{ wml.tag.filter{ side = 1, id = table.concat(ids, ",") },
		variable = "sw_logistics_buffer", kill = true }
	local count = #wml.array_access.get("sw_logistics_buffer")
	for i = 0, count - 1 do
		-- A fresh underlying id is assigned on restore (units/unit.cpp
		-- set_underlying_id), so restored units can never collide.
		wml.variables["sw_logistics_buffer[" .. i .. "].underlying_id"] = nil
		wesnoth.wml_actions.set_variables{ name = "sw_stashed_heroes", mode = "append",
			to_variable = "sw_logistics_buffer[" .. i .. "]" }
	end
	wml.variables.sw_logistics_buffer = nil
	core.log("logistics", count .. " recall-list unit(s) set aside for this " .. (space and "space" or "ground") .. " battle")
end

return logistics
